 function clickAsset(a:any,key:string){if(assetHold.current.fired&&assetHold.current.key===key){assetHold.current.fired=false;return}if(selecting)toggleAsset(key);else inspect(a)}
 useEffect(()=>{setSelecting(false);setSelectedKeys([]);cancelAssetHold();assetHold.current.fired=false;return cancelAssetHold},[project,view]);
 useEffect(()=>{window.addEventListener('scroll',cancelAssetHold,true);window.addEventListener('blur',cancelAssetHold);return()=>{cancelAssetHold();window.removeEventListener('scroll',cancelAssetHold,true);window.removeEventListener('blur',cancelAssetHold)}},[]);
 const studioHeader=useRef<HTMLElement>(null);
 useEffect(()=>{const header=studioHeader.current;if(!header)return;const measure=()=>document.documentElement.style.setProperty('--studio-header-height',header.getBoundingClientRect().height+'px');measure();const observer=new ResizeObserver(measure);observer.observe(header);return()=>observer.disconnect()},[]);
 const pendingScroll=useRef<number|null>(null),loadedProject=useRef<string|null>(null);
 useEffect(()=>{const saved=restoreNavigation();setProject(initialComposerProject??saved.project);setView(initialComposerProject!==undefined?'Composer':saved.view as View);setFilter(saved.filter);setQuery(saved.query);setScene(saved.scene);pendingScroll.current=saved.scroll;setNavigationReady(true)},[]);
 useEffect(()=>{if(!navigationReady)return;history.replaceState(null,'',(view==='Composer'?'/composer':'/')+'?project='+encodeURIComponent(project)+'#'+view);let timer:ReturnType<typeof setTimeout>;const persist=()=>{try{localStorage.setItem(navigationKey,JSON.stringify({project,view,filter,query,scene,scroll:pendingScroll.current??window.scrollY}))}catch{}};const onScroll=()=>{clearTimeout(timer);timer=setTimeout(persist,150)};persist();window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('pagehide',persist);document.addEventListener('visibilitychange',persist);return()=>{clearTimeout(timer);window.removeEventListener('scroll',onScroll);window.removeEventListener('pagehide',persist);document.removeEventListener('visibilitychange',persist)}},[navigationReady,project,view,filter,query,scene]);
 useEffect(()=>{if(!navigationReady||loading||error||pendingScroll.current===null)return;const frame=requestAnimationFrame(()=>{window.scrollTo(0,pendingScroll.current||0);pendingScroll.current=null});return()=>cancelAnimationFrame(frame)},[navigationReady,loading,error]);
 useEffect(()=>{if(!navigationReady)return;setOnline(navigator.onLine);const connected=()=>{setOnline(true);void syncLocalProjects();refresh()},disconnected=()=>setOnline(false);window.addEventListener('online',connected);window.addEventListener('offline',disconnected);return()=>{window.removeEventListener('online',connected);window.removeEventListener('offline',disconnected)}},[navigationReady,project]);
 const localMode=syncMessage&&syncMessage!=='Synced to Xstudio';
 const connectionState=!online||error||localMode?'disconnected':loading?'syncing':'connected';
 const connectionLabel=connectionState==='disconnected'?(localMode?'Local workspace':'Disconnected'):connectionState==='syncing'?'Connecting…':'Connected';
 async function refresh(){const ticket=++request.current;setLoading(true);setError('');try{if(!project){const r=await fetch('/api/projects');if(!r.ok)throw Error(r.status===401?'Sign in to load your private studio.':'Could not load projects. Please retry.');const list:any=await r.json();if(ticket===request.current){setManifest(empty);setProjects(list.projects);setDeletedProjects(list.deleted_projects||[])}return}const [a,b]=await Promise.all([fetch('/api/manifest?project='+encodeURIComponent(project)),fetch('/api/projects')]);if(a.status===423&&b.ok){const list:any=await b.json();if(ticket===request.current){setManifest(empty);setProjects(list.projects);setView('Projects');setProject('');setModal(null)}return}if(!a.ok||!b.ok)throw Error(a.status===401||b.status===401?'Sign in to load your private studio.':'Could not load your studio. Please retry.');const [m,p]=await Promise.all([a.json(),b.json()]);if(ticket===request.current){setManifest(m);setProjects((p as any).projects);setDeletedProjects((p as any).deleted_projects||[])}}catch(e){if(ticket===request.current)setError((e as Error).message==='Failed to fetch'?'Connection unavailable. Your local workspace is preserved.':(e as Error).message)}finally{if(ticket===request.current)setLoading(false)}}
 useEffect(()=>{const update=()=>void refresh();window.addEventListener('xce-refresh',update);return()=>window.removeEventListener('xce-refresh',update)},[project]);
 useEffect(()=>{if(!navigationReady)return;if(loadedProject.current&&loadedProject.current!==project)setScene('all');loadedProject.current=project;setSelectedKeys([]);setSelectedTrashKeys([]);setSelecting(false);setManifest(empty);refresh();return()=>{request.current++}},[project,navigationReady]);
 useEffect(()=>{if(modal)dialog.current?.showModal();else dialog.current?.close();if(modal&&dialog.current)dialog.current.scrollTop=0},[modal]);
 const refs=Object.values(manifest.references||{}) as any[];
 const assets=Object.entries(manifest.manifest_store||{}).flatMap(([category,items]:any)=>Object.values(items).map((a:any)=>({...a,category})));
