 const isLost=project==='xce-lost-assets';
 const previousProject=useRef('');
 const selectedProjectTitle=projects.find(p=>p.id===(isLost?previousProject.current:project))?.title;
 function openLostAssets(){if(!isLost)previousProject.current=project;setProject('xce-lost-assets');setSelectedKeys([]);setSelecting(false);setModal(null);go('LostAssets')}
 function navigate(v:View){if(isLost){setProject(previousProject.current);setSelectedKeys([]);setSelecting(false)}go(v)}

 const pageTrail=useRef<{view:View,project:string}[]>([]),trailBack=useRef(false);
 useEffect(()=>{if(!navigationReady)return;const trail=pageTrail.current;if(trailBack.current){trailBack.current=false;}else if(!trail.length||trail[trail.length-1].view!==view||trail[trail.length-1].project!==project){trail.push({view,project});if(trail.length>50)trail.shift();}},[navigationReady,view,project]);
 function backPage(){const trail=pageTrail.current;if(trail.length>1){trail.pop();const prior=trail[trail.length-1];trailBack.current=true;setProject(prior.project);setView(prior.view);setQuery('');setModal(null);}else navigate(hasProject&&!isLost&&view!=='Workspace'?'Workspace':'Studio')}
 const title=hasProject?(manifest.campaign_name||project):'Choose a project';
 const imageUrl=(id:string,deleted=false)=>'/api/manifest?project='+encodeURIComponent(project)+'&file='+encodeURIComponent(id)+(deleted?'&deleted=1':'');
 function referenceName(a:any){return a.name&&a.name!==a.id?a.name:a.asset_name||'Reference image'}
 function smallReference(id:string,deleted=false){return <span className="reference-thumb"><ImagePlus size={15} aria-hidden="true"/><PreviewImage src={imageUrl(id,deleted)} alt="" loading="lazy" onError={e=>{e.currentTarget.hidden=true}}/></span>}
 function openProjects(mode:'create'|'open'='create'){setProjectMode(mode);setProjectError('');setNewName('');setNewId('');setIdEdited(false);setModal('project')}
