 function thumbnail(a:any){const id=assetPreviewReference(a,manifest.references);return id?<PreviewImage thumbnail src={imageUrl(id)} alt={a.name||a.asset_id||a.id} loading="lazy"/>:<div className="asset-placeholder"><Aperture size={36}/><span>{a.category==='references'?'REFERENCE':'AWAITING IMAGE'}</span></div>}
 const poolReferences=unassignedReferences(manifest) as any[];
 const libraryGroups=groupedLibraryReferences(refs);
 const savedSceneImages=libraryGroups.find(g=>g.folder==='Scenes')?.records||[];
 function poolName(a:any){const name=referenceName(a).replace(/\.[^.]+$/,'');return name.length>18?name.slice(0,12)+'…'+name.slice(-4):name}
 const searchResults=useRef<HTMLDivElement>(null);
 const searchTerm=query.trim().toLocaleLowerCase();
 const searchableRecords=[...assets,...refs.map(r=>({...r,category:'references',asset_id:r.id}))];
 const matches=searchableRecords.filter(a=>{const text=[a.name,a.asset_id,a.id,a.category,a.role,a.asset_type].filter(Boolean).join(' ').normalize('NFKC').toLocaleLowerCase();return searchTerm.normalize('NFKC').split(/\s+/).every(term=>text.includes(term))});
 const referenceSection=useRef<HTMLDetailsElement>(null),pendingReferences=useRef(false);
